ven.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/694215/ivanov.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789026333477","key":{"id":1217},"before":{"id":1217,"title":"En ik herinner me Titus Broederland","isbn_10":null,"isbn_13":"9789026333477","work_id":1217,"language":null,"publisher":"Ambo|Anthos","created_at":"2026-09-03T19:14:13.706418+00:00","open_library_edition_id":"OL47310554M"},"after":{"id":1217,"title":"En ik herinner me Titus Broederland","isbn_10":null,"isbn_13":"9789026333477","work_id":1217,"language":"nld","publisher":"Ambo|Anthos","created_at":"2026-09-03T19:14:13.706418+00:00","open_library_edition_id":"OL47310554M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789026333477","key":{"edition_id":1217},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-005-20261031","evidence":[{"url":"https://metadata.isbn.nl/805627/en-ik-herinner-me-titus-broederland.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/805627/en-ik-herinner-me-titus-broederland.html","checkedAt":"2026-10-31T20:13:04.636Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"821be4845eadf178d3396cc578d48753bac40b524cd9276036738486b8891917"},{"url":"https://metadata.isbn.nl/ie_fcache/0000184191_En_ik_herinner_me_Titus_Broederland_0_0.jpg","checkedAt":"2026-10-31T20:22:56.481Z","http":200,"sha256":"c8b00a5973446cb2491fe02092061da5bfb727ea14f3d6c82bcc6e5c8484a734","bytes":94383,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"No conflicting identity or format evidence found in reviewed exact-edition and content sources."}],"edi