it hij slachtoffers van een plaatselijke overstroming te helpen hun verhaal te vertellen. Van Dis verbindt klimaatdreiging en politieke ontkenning met de vraag wanneer iemand weigert nog langer mee te buigen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1399896/klifi.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789038812915","key":{"isbn_13":"9789038812915"},"before":null,"after":{"work_id":1410,"title":"De man zonder ziekte","isbn_13":"9789038812915","isbn_10":"9038812914","language":"nld","publisher":"Singel Uitgeverijen","open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789038812915","key":{"edition_id":"@edition:9789038812915"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-005-20261031","evidence":[{"url":"https://www.dbnl.org/tekst/anbe001lexi01_01/lvlw00230.php","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/203213/de-man-zonder-ziekte.html","checkedAt":"2026-10-31T20:25:01.202Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"34362c0ea8138d604b9f67292a3141814d5831a1de2c66b8a0ba201f40b4756b"},{"url":"https://metadata.isbn.nl/ie_fcache/0000464311_De_man_zonder_ziekte_0_0.jpg","checkedAt":"2026-10-31T20:30:04.991Z","http":200,"sha256":"fb40dbd44940c53722d2f20a4546b5f7ac28da2b042e9879864b845ea4a1142f","bytes":258809,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"CurrentISBN9783462046601 is German, already ger, despite Dutch stored title. Do not convert it to Dutch. Add exact Dutch paperback9789038812915.5Jan/10Jan2023 publisher date conflict retained; German title correc