 plannen hebben. Het verhaal verbindt haar ontwikkeling met de vraag hoe bescherming mogelijk blijft wanneer politiek, vooroordelen en oorlog steeds dichterbij komen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1794508/het-bloed-van-de-elfen.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789000332007","key":{"isbn_13":"9789000332007"},"before":null,"after":{"work_id":183,"title":"Spotgaai","isbn_13":"9789000332007","isbn_10":"9000332001","language":"nld","publisher":"Uitgeverij Unieboek | Het Spectrum","open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789000332007","key":{"edition_id":"@edition:9789000332007"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-005-20261031","evidence":[{"url":"https://metadata.isbn.nl/203644/mockingjay.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/203644/mockingjay.html","checkedAt":"2026-10-31T20:18:55.731Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"5151974b9e4db844d321f8e19e7745167fa4a583a63692c5c143cce982dd2ec5"},{"url":"https://metadata.isbn.nl/ie_fcache/0000118751_Spotgaai_0_0.jpg","checkedAt":"2026-10-31T20:30:12.455Z","http":200,"sha256":"dac173d0349ff4652520cf90b265acb0bada410b14bde87096dae2750d6dc4c7","bytes":43216,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"No conflicting identity or format evidence found in reviewed exact-edition and content sources."}],"edition_id":"@edition:9789000332007","work_id":183,"bound_author_id":89,"bound_title":"Spotgaai","bound_language":"nld","bound_isbn13":"9789000332007","format":"hardcov