rachten worden toegeschreven, is gevonden maar vervolgens in vijandige handen geraakt. Rhand Altor wordt meegesleurd in de jacht om hem terug te krijgen. Wat een zoektocht naar een verloren voorwerp lijkt, raakt aan een veel grotere strijd. Onderweg wordt steeds moeilijker te ontkomen aan de rol die anderen voor Rhand verwachten en aan zijn eigen onzekere toekomst.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1543180/de-grote-jacht.html","provenance":"original_source_reviewed_summary"}}],"bindings":[{"work":{"id":1166,"title":"Dit kan niet waar zijn","cover_id":null,"subjects":null,"subtitle":null,"author_id":682,"work_type":null,"created_at":"2026-09-03T19:12:23.498756+00:00","source_type":"open_library","open_library_id":"OL22937543W","first_publish_year":2015,"native_identity_key":null},"author":{"id":682,"name":"Joris Luyendijk","created_at":"2026-09-03T19:12:21.43675+00:00","open_library_id":"OL3171583A"}},{"work":{"id":1167,"title":"De zeven vinkjes","cover_id":null,"subjects":null,"subtitle":null,"author_id":682,"work_type":null,"created_at":"2026-09-03T19:12:25.778005+00:00","source_type":"open_library","open_library_id":"OL28216089W","first_publish_year":2022,"native_identity_key":null},"author":{"id":682,"name":"Joris Luyendijk","created_at":"2026-09-03T19:12:21.43675+00:00","open_library_id":"OL3171583A"}},{"work":{"id":1177,"title":"De Omwenteling","cover_id":null,"subjects":null,"subtitle":null,"author_id":690,"work_type":null,"created_at":"2026-09-03T19:12:50.685331+00:00","source_type":"open_library","open_library_id":"OL34961957W","first_publish_year":2022,"native_identity_key":null},"author":{"id":690,"name":"Suzanna Jansen","created_at":"2026-09-03T19:12:48.438789+00:00","open_library_id":"OL10830166A"}},{"work":{"id":1179,"title":"De weduwnaar","cover_id":null,"subjects":null,"subtitle":null,"author_id":692,"work_type":null,"created_at":"2026-09-03T19:12:55.402741+00:00","source_type":"open_l